window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[366]={"id":"366","numero":366,"titre":"Exposition accidentelle aux liquides biologiques","objectifs":[{"id":"366-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un accident d’exposition accidentelle aux liquides biologiques (EALB) et les situations s’y rapportant","contenu":"<p>L'<span class=\"kw-def\">EALB</span> (ou <span class=\"kw-def\">AEV</span> — <strong>accident d'exposition au risque de transmission <span class=\"kw-etio\">virale</span></strong>) désigne tout <span class=\"kw-def\">contact</span> accidentel avec du <span class=\"kw-clinique\">sang</span> ou un <span class=\"kw-clinique\">liquide biologique</span> potentiellement contaminant, exposant aux trois virus à transmission par le sang : <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>.</p>\n      <p>Deux grands contextes :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Cadre professionnel</span> — <span class=\"kw-def\">AES</span> (accident d'exposition au sang)</strong> : <span class=\"kw-clinique\">piqûre</span> avec une aiguille, <span class=\"kw-clinique\">coupure</span> avec un objet tranchant, <span class=\"kw-clinique\">projection</span> sur une plaie, une peau lésée ou une muqueuse.</li>\n        <li><strong><span class=\"kw-def\">Cadre non professionnel</span></strong> : <span class=\"kw-clinique\">exposition sexuelle</span> (AES = accident d'exposition sexuelle), <span class=\"kw-clinique\">partage de matériel d'injection</span> de drogue.</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span> médicale.</strong> Agir idéalement dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 4 h</span>, à défaut dans les <span class=\"kw-chiffre\">&lt; 48 h</span>. Au-delà de <span class=\"kw-chiffre\">48 h</span>, le <span class=\"kw-ttt\">traitement post-exposition (TPE)</span> est <span class=\"kw-alerte\">inefficace</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales</em></p>","frequence":1},{"id":"366-2","rang":"A","rubrique":"Définition","titre":"Connaître les agents infectieux à risque de transmission lors d’un EALB","contenu":"<p>Trois <span class=\"kw-etio\">virus à transmission sanguine</span> sont concernés par l'<span class=\"kw-def\">EALB</span> ; le <span class=\"kw-clinique\">sang</span> est le liquide le plus à risque. Le niveau de risque dépend du <span class=\"kw-def\">virus</span>, de la <span class=\"kw-def\">nature de l'exposition</span> et du <span class=\"kw-def\">statut de la personne source</span>.</p>\n      <table >\n        <thead><tr><th>Virus</th><th>Caractéristique</th><th>Prévention spécifique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VIH</span></strong><br>immunodéficience humaine</td>\n            <td>Risque de séroconversion <span class=\"kw-alerte\">maîtrisé</span> si PEC rapide</td>\n            <td><span class=\"kw-ttt\">TPE</span> antirétroviral (<span class=\"kw-chiffre\">28 jours</span>)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VHB</span></strong><br><span class=\"kw-ttt\">hépatite B</span></td>\n            <td>Transmission la <span class=\"kw-alerte\">plus élevée</span> des trois</td>\n            <td><span class=\"kw-ttt\">Vaccination</span> ± <span class=\"kw-ttt\">immunoglobulines</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VHC</span></strong><br>hépatite C</td>\n            <td><span class=\"kw-alerte\">Aucune prophylaxie</span> ni vaccin disponible</td>\n            <td><span class=\"kw-def\">Surveillance</span> ± traitement si infection aiguë</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 167 — Hépatites virales</em></p>","frequence":1},{"id":"366-3","rang":"A","rubrique":"Définition","titre":"Connaître les facteurs de risque de transmission liés aux EALB","contenu":"<p>Le risque de séroconversion dépend du <span class=\"kw-def\">virus</span>, du <span class=\"kw-def\">type d'exposition</span> (sang <span class=\"kw-bio\">vs</span> sexuelle) et de cofacteurs.</p>\n      <table >\n        <thead>\n          <tr><th>Virus</th><th>Exposition au sang (AES)</th><th>Exposition sexuelle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VIH</span></strong></td>\n            <td>\n              <strong>Taux :</strong> <span class=\"kw-chiffre\">0,3 %</span> (exposition percutanée, source non traitée)<br>\n              <strong>↑ Risque si :</strong> source <span class=\"kw-alerte\">non traitée</span> par <span class=\"kw-ttt\">antirétroviraux</span> ; <span class=\"kw-alerte\">charge virale élevée</span> ; blessure <span class=\"kw-alerte\">profonde</span> par aiguille creuse contenant du sang\n            </td>\n            <td>\n              <strong>Taux :</strong> <span class=\"kw-chiffre\">1 %</span> (rapport anal réceptif) ; <span class=\"kw-chiffre\">0,1 %</span> (rapport vaginal insertif)<br>\n              <strong>↑ Risque si :</strong> lésions muqueuses / <span class=\"kw-clinique\">IST</span> ; menstruations ou saignement ; <span class=\"kw-alerte\">viol</span><br>\n              <strong>↓ Risque si :</strong> <span class=\"kw-clinique\">circoncision</span> (kératinisation du gland) ; ARV avec <span class=\"kw-bio\">charge virale indétectable</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VHB</span></strong></td>\n            <td><span class=\"kw-chiffre\">40 %</span> (si source <span class=\"kw-bio\">Ag HBe +</span> et virémique, sujet non immunisé)</td>\n            <td>≈ <span class=\"kw-chiffre\">50 %</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">VHC</span></strong></td>\n            <td><span class=\"kw-chiffre\">&lt; 3 %</span></td>\n            <td>Significatif uniquement si rapport <span class=\"kw-alerte\">traumatique</span> (saignement, viol)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant.</strong> Le risque <span class=\"kw-etio\">VIH</span> lors d'un rapport vaginal non traumatique est <span class=\"kw-chiffre\">nul</span> si le partenaire infecté a une <span class=\"kw-bio\">charge virale indétectable</span> sous ARV depuis <span class=\"kw-chiffre\">&gt; 6 mois</span>.\n      </div>\n      <div class=\"callout callout-info\">\n        <strong>Hors AES et exposition sexuelle.</strong> <span class=\"kw-clinique\">Les</span> trois virus (<span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VHC</span>) se transmettent aussi par <span class=\"kw-clinique\">partage de matériel d'injection</span> de drogue : aiguilles, seringues, mais aussi <span class=\"kw-clinique\">pailles</span> d'inhalation, cotons, cuillers.\n      </div>","frequence":0},{"id":"366-4","rang":"A","rubrique":"Prise en charge","titre":"Décrire les soins locaux immédiats en cas d’accident d’exposition au sang (AES)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">soins locaux</span> sont <strong>immédiats</strong> et constituent le premier geste de l'<span class=\"kw-alerte\">urgence</span>, avant toute évaluation du risque.</p>\n      <table >\n        <thead>\n          <tr><th>Situation</th><th>Conduite à tenir</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Blessure ou <span class=\"kw-clinique\">piqûre</span></strong></td>\n            <td>\n              <strong>1.</strong> <span class=\"kw-alerte\">Ne pas faire saigner</span> (le <span class=\"kw-clinique\">saignement</span> crée une <span class=\"kw-clinique\">brèche capillaire</span> favorisant l'infection)<br>\n              <strong>2.</strong> <span class=\"kw-clinique\">Nettoyage immédiat</span> à l'<span class=\"kw-clinique\">eau courante et savon</span> (<span class=\"kw-clinique\">détersion</span>, élimination des matières organiques)<br>\n              <strong>3.</strong> <span class=\"kw-clinique\">Rinçage</span><br>\n              <strong>4.</strong> <span class=\"kw-clinique\">Antisepsie</span> par <span class=\"kw-def\">contact</span> d'un <span class=\"kw-ttt\">antiseptique</span> pendant <span class=\"kw-chiffre\">≥ 5 minutes</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Projection <span class=\"kw-clinique\">muqueuse</span></strong> (œil, bouche)</td>\n            <td><span class=\"kw-clinique\">Rinçage</span> immédiat abondant au <span class=\"kw-ttt\">sérum physiologique</span> (ou à l'<span class=\"kw-clinique\">eau</span>), <span class=\"kw-chiffre\">≥ 5 minutes</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">\n        <strong>Piège classique.</strong> <span class=\"kw-alerte\">Ne pas utiliser de produit hydro-alcoolique</span> sur une plaie : il favorise le saignement, donc la transmission. Et <span class=\"kw-alerte\">ne pas faire saigner</span> la plaie.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 184 — Accident - maladie professionnel</em></p>","frequence":2},{"id":"366-5","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription des sérologies à réaliser chez la personne source au cours des EALB","contenu":"<p>Le <span class=\"kw-def\">statut sérologique de la personne source</span> est recherché <strong>systématiquement</strong>, le plus rapidement possible, sauf <span class=\"kw-alerte\">refus exprès</span> du patient.</p>\n      <table >\n        <thead>\n          <tr><th>Caractère</th><th>Examens chez la personne source</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Systématique</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">Sérologie VHC</span> :</strong> si positive → rechercher la réplication <span class=\"kw-etio\">virale</span> (<span class=\"kw-bio\">ARN VHC</span>)<br>\n              <strong><span class=\"kw-bio\">Sérologie VIH</span> :</strong> privilégier <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">tests de diagnostic rapide (TDR)</span>, résultat en <span class=\"kw-chiffre\">&lt; 1 h</span> ; si positif → <span class=\"kw-bio\">charge virale VIH</span> en <span class=\"kw-alerte\">urgence</span> + génotype de résistance aux <span class=\"kw-ttt\">antirétroviraux</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non systématique</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">Sérologie VHB</span> :</strong> indiquée si la victime n'est pas immunisée (immunité prouvée par <span class=\"kw-bio\">Ac anti-HBs &gt; 10 UI/L</span> présent ou passé)<br>\n              <strong>Recherche d'<span class=\"kw-bio\">Ag HBs</span></strong> chez la source<br>\n              <strong>Réplication <span class=\"kw-etio\">virale</span> (<span class=\"kw-bio\">ADN VHB</span>)</strong> si <span class=\"kw-bio\">Ag HBs</span> positif\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Le <span class=\"kw-bio\">TDR VIH</span> chez la source (résultat <span class=\"kw-chiffre\">&lt; 1 h</span>) conditionne l'indication du <span class=\"kw-ttt\">TPE</span> chez la personne exposée — d'où l'<span class=\"kw-alerte\">urgence</span>.\n      </div>","frequence":0},{"id":"366-6","rang":"B","rubrique":"Prise en charge","titre":"Citer les principales indications devant conduire à une prophylaxie post-exposition (PPE) au risque exposant au virus de l’immunodéficience humaine (VIH)","contenu":"<p>Le <span class=\"kw-ttt\">TPE</span> (traitement antirétroviral post-exposition) doit être débuté en <span class=\"kw-alerte\">urgence</span> : au mieux <span class=\"kw-chiffre\">&lt; 4 h</span>, sinon <span class=\"kw-chiffre\">&lt; 48 h</span> (<span class=\"kw-alerte\">inefficace au-delà</span>). Un « <span class=\"kw-ttt\">kit</span> » des 48 premières heures est fourni à la victime.</p>\n\n      <p><strong>Indications selon le type d'AES</strong> (gravité de l'exposition × statut de la source) :</p>\n      <table >\n        <thead>\n          <tr><th>Risque (type d'exposition)</th><th>Source <span class=\"kw-etio\">VIH</span><br>CV détectable</th><th>Source VIH<br>CV indétectable</th><th><span class=\"kw-bio\">Sérologie</span> inconnue</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Important</strong> — piqûre profonde, aiguille creuse, IV (artère/veine)</td>\n            <td><span class=\"kw-ttt\">TPE</span></td>\n            <td>Non</td>\n            <td><span class=\"kw-ttt\">TPE</span></td>\n          </tr>\n          <tr>\n            <td><strong>Intermédiaire</strong> — coupure au bistouri ; aiguille IM/SC ; aiguille pleine ; exposition cutanéo-muqueuse &gt;<span class=\"kw-chiffre\"> 15 min</span></td>\n            <td><span class=\"kw-ttt\">TPE</span></td>\n            <td>Non</td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td><strong>Faible</strong> — autres cas ; seringues abandonnées ; morsures, crachats, griffures</td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Non</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Indications selon l'exposition sexuelle</strong> (groupe à <span class=\"kw-def\">prévalence</span> élevée = HSH multipartenaire, travailleur du sexe, origine d'une région à prévalence <span class=\"kw-etio\">VIH</span> &gt;<span class=\"kw-chiffre\"> 1 %</span>, usager de drogue injectable) :</p>\n      <table >\n        <thead>\n          <tr><th>Type de rapport</th><th>CV détectable</th><th>CV indétectable</th><th>Inconnue<br>prévalence élevée</th><th>Inconnue<br>prévalence faible</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Rapport <span class=\"kw-clinique\">anal</span> / <span class=\"kw-clinique\">vaginal</span> (insertif ou réceptif) ; fellation réceptive avec éjaculation</td>\n            <td><span class=\"kw-ttt\">TPE</span></td>\n            <td>Non</td>\n            <td><span class=\"kw-ttt\">TPE</span></td>\n            <td>Non</td>\n          </tr>\n          <tr>\n            <td>Fellation insertive ou réceptive sans éjaculation</td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Non</td>\n            <td>Non</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p><strong>Modalités du <span class=\"kw-ttt\">TPE</span> :</strong></p>\n      <ul>\n        <li><strong>Molécules :</strong> <span class=\"kw-ttt\">trithérapie</span>, choix préférentiel <span class=\"kw-ttt\">ténofovir + emtricitabine + rilpivirine</span> (ténofovir + emtricitabine couvre aussi le <span class=\"kw-etio\">VHB</span>).</li>\n        <li><strong>Durée :</strong> <span class=\"kw-chiffre\">28 jours</span>.</li>\n        <li><strong>Consultation référent <span class=\"kw-etio\">VIH</span></strong> à <span class=\"kw-chiffre\">2 à 4 jours</span> si débuté hors centre référent (urgences).</li>\n        <li><strong><span class=\"kw-def\">Suivi</span> <span class=\"kw-ttt\">biologique</span> :</strong> <span class=\"kw-bio\">créatinine</span> + <span class=\"kw-bio\">transaminases</span> à <span class=\"kw-chiffre\">J15</span>.</li>\n        <li><strong>Préservatif :</strong> jusqu'à la <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">VIH</span> à <span class=\"kw-chiffre\">6 semaines</span> (sans <span class=\"kw-ttt\">TPE</span>) ou <span class=\"kw-chiffre\">12 semaines</span> (avec TPE).</li>\n      </ul>\n\n      <p><strong>Calendrier de <span class=\"kw-def\">suivi</span></strong> de la personne exposée :</p>\n      <table >\n        <thead>\n          <tr><th>Échéance</th><th>Exposition au sang (AES)</th><th>Exposition sexuelle</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">J1-J4</span></strong><br>(jusqu'à <span class=\"kw-chiffre\">J7</span> si AES)</td>\n            <td>Bilan initial : <span class=\"kw-bio\">sérologie VIH</span> ; <span class=\"kw-bio\">sérologie VHB</span> ; <span class=\"kw-bio\">ALAT</span> ; <span class=\"kw-bio\">créatinine</span> ; <span class=\"kw-bio\">β-hCG</span> si <span class=\"kw-ttt\">TPE</span></td>\n            <td>Idem AES + <span class=\"kw-bio\">PCR chlamydia et gonocoque</span> ; <span class=\"kw-bio\">test de grossesse</span> si indication de <span class=\"kw-ttt\">TPE</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">S2</span></strong> (<span class=\"kw-chiffre\">J15</span>)</td>\n            <td><span class=\"kw-bio\">ALAT</span> + <span class=\"kw-bio\">créatinine</span> si <span class=\"kw-ttt\">TPE</span> (ou crainte de défaut d'observance)</td>\n            <td><span class=\"kw-bio\">ALAT</span> + <span class=\"kw-bio\">créatinine</span> si <span class=\"kw-ttt\">TPE</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">S6</span></strong></td>\n            <td><span class=\"kw-bio\">sérologie VIH</span> ; <span class=\"kw-bio\">ALAT</span> ; <span class=\"kw-bio\">sérologie VHC</span> (+ <span class=\"kw-bio\">ARN VHC</span> si source ARN <span class=\"kw-etio\">VHC</span>+)</td>\n            <td><span class=\"kw-bio\">sérologie VIH</span> ; <span class=\"kw-bio\">sérologie VHC</span> si HSH / source <span class=\"kw-etio\">VHC</span>+ ; <span class=\"kw-bio\">PCR chlamydia et gonocoque</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">3 mois</span></strong> (S12)</td>\n            <td><span class=\"kw-bio\">sérologie VIH</span> (si <span class=\"kw-ttt\">TPE</span>) ; <span class=\"kw-bio\">sérologie VHC</span> ; <span class=\"kw-bio\">marqueurs VHB</span> si non immunisé</td>\n            <td><span class=\"kw-bio\">sérologie VIH</span> (si <span class=\"kw-ttt\">TPE</span>) ; <span class=\"kw-bio\">sérologie VHC</span> si HSH / source <span class=\"kw-etio\">VHC</span>+ ; <span class=\"kw-bio\">marqueurs VHB</span> si non immunisé</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Rythme du <span class=\"kw-def\">suivi</span> <span class=\"kw-etio\">VIH</span></strong> selon l'exposition : <strong>AES</strong> → <span class=\"kw-chiffre\">6 semaines</span> + <span class=\"kw-chiffre\">3 mois</span> ; <strong>exposition sexuelle avec <span class=\"kw-ttt\">TPE</span></strong> → <span class=\"kw-chiffre\">6 semaines</span> + <span class=\"kw-chiffre\">3 mois</span> ; <strong>sans TPE</strong> → <span class=\"kw-chiffre\">6 semaines</span>.</p>\n\n      <div class=\"callout callout-info\">\n        <strong>Efficacité.</strong> Une monothérapie de <span class=\"kw-ttt\">zidovudine (AZT)</span> réduisait déjà de <span class=\"kw-chiffre\">80 %</span> le risque après blessure à haut risque. <span class=\"kw-clinique\">Les</span> échecs sous <span class=\"kw-ttt\">TPE</span> bien conduit sont <span class=\"kw-bio\">exceptionnels</span> (défaut d'observance ou résistance <span class=\"kw-etio\">virale</span>).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":2},{"id":"366-7","rang":"B","rubrique":"Prise en charge","titre":"Décrire les modalités de prise en charge des expositions sexuelles lors de violences (viol)","contenu":"<p>Chez la <span class=\"kw-def\">victime de viol</span>, deux évaluations sont à réaliser <strong>en <span class=\"kw-alerte\">urgence</span></strong> :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Évaluation médico-légale</span></strong> — examen avec <span class=\"kw-clinique\">prélèvements</span> en vue d'identifier l'agresseur, réalisé par un <span class=\"kw-clinique\">médecin légiste</span>, sur <span class=\"kw-clinique\">réquisition de justice</span> après <span class=\"kw-clinique\">dépôt de plainte</span>.</li>\n        <li><strong><span class=\"kw-def\">Évaluation des risques infectieux et de grossesse</span></strong> — par le légiste ou l'<span class=\"kw-clinique\">urgentiste</span>, en concertation avec un <span class=\"kw-clinique\">médecin référent VIH</span>.</li>\n      </ul>\n      <p>La seconde évaluation comporte :</p>\n      <ul>\n        <li>Récupérer la <span class=\"kw-clinique\">date des dernières règles</span>.</li>\n        <li>Bilan sérologique initial : <span class=\"kw-etio\">VIH</span>, <span class=\"kw-bio\">VDRL-TPHA</span> (<span class=\"kw-clinique\">syphilis</span>), <span class=\"kw-bio\">hépatites B et C</span>.</li>\n        <li><span class=\"kw-ttt\">Contraception d'urgence</span> (pilule du lendemain) : <span class=\"kw-ttt\">lévonorgestrel</span> 1 cp.</li>\n        <li>Proposer un <span class=\"kw-ttt\">TPE</span> si indiqué ; proposer une <span class=\"kw-ttt\">sérovaccination VHB</span> si indiqué.</li>\n        <li>Organiser le <span class=\"kw-clinique\">suivi sérologique</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> En cas d'exposition sexuelle <span class=\"kw-alerte\">traumatique</span> (viol), le <span class=\"kw-alerte\">risque VHC</span> doit être pris en compte : <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-ttt\">biologique</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 12 — Violences sexuelles · 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":1},{"id":"366-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","contenu":"<p><span class=\"kw-clinique\">Les</span> indications sont <strong>les mêmes</strong> en cas d'AES que d'exposition sexuelle. La décision croise le <span class=\"kw-def\">statut vaccinal de la personne exposée</span> et le <span class=\"kw-def\">statut VHB (Ag HBs) de la source</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Sujet exposé</th><th>Source <span class=\"kw-bio\">Ag HBs</span> positif</th><th>Source Ag HBs inconnu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Vacciné répondeur</strong> (<span class=\"kw-bio\">Ac anti-HBs &gt; 10 UI/L</span>)</td>\n            <td>Rien (<span class=\"kw-bio\">protégé</span>)</td>\n            <td>Rien</td>\n          </tr>\n          <tr>\n            <td><strong>Vacciné non répondeur / titre inconnu</strong></td>\n            <td><span class=\"kw-ttt\">Immunoglobulines</span> (non nécessaires si ADN <span class=\"kw-etio\">VHB</span> indétectable chez la source + ténofovir dans le <span class=\"kw-ttt\">TPE</span>)</td>\n            <td>Rien, ou <span class=\"kw-ttt\">immunoglobulines</span> si source à risque (pays d'endémie, HSH, usager de drogue IV, partenaires multiples)</td>\n          </tr>\n          <tr>\n            <td><strong>Non vacciné</strong></td>\n            <td><span class=\"kw-ttt\">Immunoglobulines + vaccin</span></td>\n            <td><span class=\"kw-ttt\">Vaccin</span> (+ immunoglobulines si source à risque)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Conduite selon le titre d'<span class=\"kw-bio\">Ac anti-HBs</span></strong> chez un sujet vacciné jamais contrôlé :</p>\n      <ul>\n        <li><span class=\"kw-bio\">Ac anti-HBs &lt; 10 UI/L</span> → <span class=\"kw-ttt\">vaccination</span>.</li>\n        <li><span class=\"kw-bio\">Ac anti-HBs &gt; 10 UI/L</span> → <span class=\"kw-bio\">répondeur protégé</span>, risque de transmission <span class=\"kw-chiffre\">nul</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Suivi</span></strong> chez un sujet non protégé : <span class=\"kw-bio\">transaminases</span> et <span class=\"kw-bio\">marqueurs VHB</span> (<span class=\"kw-bio\">Ag HBs</span>, Ac anti-HBc, Ac anti-HBs) à <span class=\"kw-chiffre\">3 mois</span>.</p>\n      <div class=\"callout callout-info\">\n        <strong>Astuce.</strong> Si un <span class=\"kw-ttt\">TPE VIH</span> est indiqué, privilégier <span class=\"kw-ttt\">emtricitabine-ténofovir</span> qui a aussi une bonne activité sur le <span class=\"kw-etio\">VHB</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 167 — Hépatites virales</em></p>","frequence":0},{"id":"366-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","contenu":"<p>Près de <span class=\"kw-chiffre\">50 %</span> des AES sont dus au <span class=\"kw-alerte\">non-respect des précautions standard</span> d'hygiène.</p>\n      <ul>\n        <li><strong>Précautions standard :</strong> <span class=\"kw-clinique\">port de gants</span> pour <span class=\"kw-clinique\">les</span> gestes à risque ; <span class=\"kw-alerte\">ne jamais recapuchonner</span> les aiguilles ; jeter immédiatement les objets piquants ou tranchants dans un <span class=\"kw-clinique\">conteneur (OPCT)</span> ad hoc.</li>\n        <li><strong>Matériel sécurisé :</strong> sa mise à disposition a fait diminuer notablement la fréquence des AES en milieu hospitalier.</li>\n        <li><strong><span class=\"kw-ttt\">Vaccination VHB</span> obl<span class=\"kw-chiffre\">iga</span>toire</strong> chez <span class=\"kw-clinique\">les</span> professionnels de santé : élément <span class=\"kw-alerte\">majeur</span> de prévention.</li>\n      </ul>\n      <p><strong>Reconnaissance en accident du travail (AT) / maladie professionnelle (MP) :</strong></p>\n      <ul>\n        <li>Toute infection <span class=\"kw-etio\">acquise</span> après AES peut être reconnue en <span class=\"kw-def\">AT</span>, y compris le <span class=\"kw-etio\">VIH</span> : déclaration par l'employeur <span class=\"kw-chiffre\">&lt; 48 h</span> + certificat médical initial.</li>\n        <li>Pour reconnaître une infection <span class=\"kw-etio\">VIH</span> en AT : source porteuse du VIH au moment de l'accident ; <span class=\"kw-bio\">sérologie</span> VIH de l'exposé <span class=\"kw-bio\">négative</span> dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">8 jours</span> ; séroconversion dans un délai de <span class=\"kw-chiffre\">6 à 12 semaines</span>.</li>\n        <li><span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">tuberculose</span>, <span class=\"kw-etio\">rage</span>, <span class=\"kw-etio\">gale</span> peuvent être reconnus en <span class=\"kw-def\">MP</span> chez un soignant (tableau de MP) — <span class=\"kw-alerte\">ce qui n'est pas le cas du VIH</span>.</li>\n      </ul>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 184 — Accident - maladie professionnel</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Urgence</span> médicale :</strong> agir au mieux dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">&lt; 4 h</span>, à défaut dans les <span class=\"kw-chiffre\">&lt; 48 h</span>.<br><strong>Au-delà :</strong> le <span class=\"kw-ttt\">TPE</span> antirétroviral est <span class=\"kw-alerte\">inefficace</span> après <span class=\"kw-chiffre\">48 h</span>.<br><strong>Soins locaux :</strong> <span class=\"kw-clinique\">immédiats</span>, avant toute évaluation du risque.<br><strong>Statut de la source :</strong> recherché en urgence — <span class=\"kw-bio\">TDR VIH</span> en <span class=\"kw-chiffre\">&lt; 1 h</span>, conditionne l’indication du <span class=\"kw-ttt\">TPE</span>.</p>","hospit":"<p><strong>Filière d’<span class=\"kw-alerte\">urgence</span></strong></p><ul><li>Prise en charge aux <span class=\"kw-clinique\">urgences</span> ou en consultation dédiée : un « <span class=\"kw-ttt\">kit</span> » des <span class=\"kw-chiffre\">48 premières heures</span> de <span class=\"kw-ttt\">TPE</span> est remis à la victime.</li><li>Si <span class=\"kw-ttt\">TPE</span> débuté hors centre référent : <span class=\"kw-clinique\">consultation référent VIH</span> à <span class=\"kw-chiffre\">2 à 4 jours</span> pour <span class=\"kw-def\">réévaluation</span>.</li></ul><p><strong>Accident du travail (AES professionnel)</strong></p><ul><li><span class=\"kw-clinique\">Déclaration d’AT</span> par l’employeur obl<span class=\"kw-chiffre\">iga</span>toire dans <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">48 h</span> + <span class=\"kw-clinique\">certificat médical initial</span> notifiant le risque de séroconversion <span class=\"kw-etio\">VIH</span>.</li><li>Toute infection <span class=\"kw-etio\">acquise</span> après AES, y compris le <span class=\"kw-etio\">VIH</span>, peut être reconnue en AT.</li></ul><p><strong>Exposition sexuelle / violences (viol)</strong></p><ul><li><span class=\"kw-clinique\">Évaluation médico-légale</span> par un <span class=\"kw-clinique\">médecin légiste</span>, sur <span class=\"kw-clinique\">réquisition de justice</span> après dépôt de plainte.</li><li><span class=\"kw-clinique\">Évaluation des risques infectieux et de grossesse</span> par l’urgentiste/légiste, en concertation avec un <span class=\"kw-clinique\">médecin référent VIH</span>.</li></ul>","redflags":"<p><strong>Situations à haut risque de transmission</strong> orientant vers une prophylaxie :</p><ul><li><span class=\"kw-alerte\">Piqûre profonde par aiguille creuse</span> contenant du sang, voie <span class=\"kw-alerte\">intraveineuse / artérielle</span> (AES le plus à risque).</li><li>Personne source <span class=\"kw-alerte\">non traitée</span> par <span class=\"kw-ttt\">antirétroviraux</span> ou à <span class=\"kw-alerte\">charge virale élevée</span>.</li><li>Rapport sexuel <span class=\"kw-alerte\">traumatique</span> : saignement, <span class=\"kw-alerte\">viol</span>, menstruations, lésions muqueuses ou <span class=\"kw-etio\">IST</span>.</li><li>Source de <span class=\"kw-bio\">statut VIH inconnu</span> appartenant à un groupe à <span class=\"kw-alerte\">prévalence élevée</span> (HSH multipartenaire, travailleur du sexe, origine d’une région à <span class=\"kw-def\">prévalence</span> <span class=\"kw-etio\">VIH</span> <span class=\"kw-chiffre\">&gt; 1 %</span>, usager de drogue injectable).</li><li>Source <span class=\"kw-bio\">Ag HBe +</span> et virémique : <span class=\"kw-alerte\">risque VHB majeur</span> (<span class=\"kw-chiffre\">40 %</span>) chez le sujet non immunisé.</li></ul>","principes":"<p><strong>1. Soins locaux immédiats</strong></p><ul><li><strong>Piqûre / blessure :</strong> <span class=\"kw-alerte\">ne pas faire saigner</span> → <span class=\"kw-clinique\">nettoyage</span> eau courante + savon → <span class=\"kw-clinique\">rinçage</span> → <span class=\"kw-clinique\">antisepsie</span> par <span class=\"kw-def\">contact</span> <span class=\"kw-chiffre\">≥ 5 min</span>.</li><li><strong>Projection muqueuse :</strong> <span class=\"kw-clinique\">rinçage</span> abondant au <span class=\"kw-ttt\">sérum physiologique</span> (ou eau), <span class=\"kw-chiffre\">≥ 5 min</span>.</li><li><span class=\"kw-ci\">Ne pas utiliser de produit hydro-alcoolique</span> sur une plaie (favorise le saignement, donc la transmission).</li></ul><p><strong>2. Risque <span class=\"kw-etio\">VIH</span> — <span class=\"kw-ttt\">TPE</span></strong></p><ul><li><span class=\"kw-ttt\">Trithérapie</span> antirétrovirale, choix préférentiel <span class=\"kw-ttt\">ténofovir + emtricitabine + rilpivirine</span>.</li><li>Débuté en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 4 h</span>, au plus tard <span class=\"kw-chiffre\">&lt; 48 h</span>), durée <span class=\"kw-chiffre\">28 jours</span>.</li><li><span class=\"kw-ttt\">Ténofovir + emtricitabine</span> couvre aussi le <span class=\"kw-etio\">VHB</span>.</li></ul><p><strong>3. Risque <span class=\"kw-etio\">VHB</span> — séro-<span class=\"kw-ttt\">vaccination</span></strong></p><ul><li>Indications identiques en AES et en exposition sexuelle.</li><li>Sujet <span class=\"kw-clinique\">non vacciné</span> → <span class=\"kw-ttt\">immunoglobulines + vaccin</span>.</li><li>Sujet vacciné jamais contrôlé → doser <span class=\"kw-bio\">Ac anti-HBs</span> : <span class=\"kw-chiffre\">&lt; 10 UI/L</span> → <span class=\"kw-ttt\">vaccination</span> ; <span class=\"kw-chiffre\">&gt; 10 UI/L</span> → <span class=\"kw-bio\">répondeur protégé</span>, risque nul.</li></ul><p><strong>4. Risque <span class=\"kw-etio\">VHC</span></strong></p><ul><li><span class=\"kw-alerte\">Aucune prophylaxie</span> ni vaccin disponible.</li><li><span class=\"kw-ttt\">Traitement antiviral</span> si infection aiguë post-exposition (séroconversion ou <span class=\"kw-bio\">PCR ARN VHC positive</span>).</li></ul><p><strong>5. Viol / partage de matériel</strong></p><ul><li><strong>Viol :</strong> <span class=\"kw-ttt\">contraception d’urgence</span> par <span class=\"kw-ttt\">lévonorgestrel</span> <span class=\"kw-chiffre\">1 cp</span>, bilan <span class=\"kw-bio\">VDRL-TPHA</span>, prise en compte du <span class=\"kw-alerte\">risque VHC</span> ; <span class=\"kw-ttt\">TPE</span> et séro-<span class=\"kw-ttt\">vaccination</span> <span class=\"kw-etio\">VHB</span> si indiqués.</li><li><strong>Partage de matériel d’injection :</strong> <span class=\"kw-ttt\">TPE</span> si source à CV détectable ou statut inconnu ; <span class=\"kw-ttt\">séro-vaccination VHB</span> ; <span class=\"kw-clinique\">surveillance VHC</span>.</li></ul>","suivi":"<p><strong>Bilan initial chez la personne exposée</strong></p><ul><li>AES → entre <span class=\"kw-chiffre\">J1-J7</span> ; exposition sexuelle → entre <span class=\"kw-chiffre\">J1-J4</span> (+ <span class=\"kw-bio\">PCR chlamydia et gonocoque</span>).</li><li><span class=\"kw-bio\">Sérologie VIH</span>, <span class=\"kw-bio\">sérologie VHC</span>, <span class=\"kw-bio\">sérologies VHB</span>, <span class=\"kw-bio\">bilan hépatique</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">test de grossesse</span> si indication de <span class=\"kw-ttt\">TPE</span>.</li></ul><p><strong>Sous <span class=\"kw-ttt\">TPE</span></strong></p><ul><li><span class=\"kw-bio\">Créatinine</span> + <span class=\"kw-bio\">transaminases</span> à <span class=\"kw-chiffre\">J15</span>.</li><li><span class=\"kw-ttt\">Préservatif</span> jusqu’à la <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">VIH</span> : <span class=\"kw-chiffre\">6 semaines</span> sans <span class=\"kw-ttt\">TPE</span>, <span class=\"kw-chiffre\">12 semaines</span> avec TPE.</li></ul><p><strong><span class=\"kw-def\">Suivi</span> virologique <span class=\"kw-etio\">VIH</span></strong></p><ul><li>AES → <span class=\"kw-chiffre\">6 semaines</span> et <span class=\"kw-chiffre\">3 mois</span>.</li><li>Exposition sexuelle avec <span class=\"kw-ttt\">TPE</span> → <span class=\"kw-chiffre\">6 semaines</span> et <span class=\"kw-chiffre\">3 mois</span> ; sans TPE → <span class=\"kw-chiffre\">6 semaines</span>.</li></ul><p><strong><span class=\"kw-def\">Suivi</span> <span class=\"kw-etio\">VHC</span> / <span class=\"kw-etio\">VHB</span></strong></p><ul><li><strong><span class=\"kw-etio\">VHC</span> :</strong> <span class=\"kw-bio\">sérologie</span> + <span class=\"kw-bio\">PCR VHC</span> + <span class=\"kw-bio\">transaminases</span> à <span class=\"kw-chiffre\">6 semaines</span>, <span class=\"kw-bio\">sérologie VHC</span> à <span class=\"kw-chiffre\">3 mois</span>.</li><li><strong><span class=\"kw-etio\">VHB</span> (sujet non protégé) :</strong> <span class=\"kw-bio\">transaminases</span> + <span class=\"kw-bio\">marqueurs VHB</span> (<span class=\"kw-bio\">Ag HBs</span>, Ac anti-HBc, Ac anti-HBs) à <span class=\"kw-chiffre\">3 mois</span>.</li></ul>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-366.pdf","label":"Pilly étudiant 2023 — item 366"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Exposition à un liquide biologique — soins locaux immédiats réalisés — Eau + savon · antisepsie ≥ 5 min · ne pas faire saigner · statut VIH de la source en urgence (TDR)","detail":"<h4>CAT — Exposition accidentelle aux liquides biologiques — Après soins locaux immédiats : indication du traitement post-exposition (<span class=\"kw-ttt\">TPE</span>) <span class=\"kw-etio\">VIH</span></h4>","branches":[{"to":"t-delai","label":"Délai supérieur à 48 h depuis l’exposition","color":"blue"},{"to":"q-type","label":"Délai inférieur à 48 h (idéalement moins de 4 h)","color":"green"}]},{"id":"t-delai","kind":"terminal","label":"TPE VIH inefficace — pas de prophylaxie antirétrovirale","color":"blue","detail":"<h4>Conduite</h4><ul><li>Le <span class=\"kw-ttt\">TPE</span> est <span class=\"kw-alerte\">inefficace au-delà de 48 h</span> : il n’est pas débuté.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Organiser le <span class=\"kw-clinique\">suivi sérologique</span> <span class=\"kw-bio\">VIH</span>, <span class=\"kw-bio\">VHC</span> et <span class=\"kw-bio\">VHB</span>.</li><li><span class=\"kw-ttt\">Séro-vaccination VHB</span> selon le statut immunitaire ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-etio\">VHC</span> (pas de prophylaxie).</li></ul>"},{"id":"q-type","kind":"decision","label":"Type d’exposition ?","branches":[{"to":"q-aes","label":"AES percutané / projection (sang)","color":"blue"},{"to":"q-sex","label":"Exposition sexuelle","color":"blue"},{"to":"t-drogue","label":"Partage de matériel d’injection / inhalation","color":"amber"}]},{"id":"q-aes","kind":"decision","label":"Gravité de l’exposition × statut VIH de la source","branches":[{"to":"t-aes-tpe","label":"Piqûre profonde, aiguille creuse IV + source CV détectable ou inconnue","color":"red"},{"to":"t-aes-notpe","label":"Faible risque ou source à CV indétectable","color":"green"}]},{"id":"t-aes-tpe","kind":"terminal","label":"TPE VIH indiqué","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Piqûre profonde</span>, <span class=\"kw-clinique\">aiguille creuse</span> ayant servi en <span class=\"kw-clinique\">IV</span> + source à <span class=\"kw-bio\">CV détectable</span> ou <span class=\"kw-bio\">sérologie inconnue</span>.</li><li><span class=\"kw-clinique\">Coupure au bistouri</span>, aiguille <span class=\"kw-clinique\">IM/SC</span> ou <span class=\"kw-clinique\">aiguille pleine</span> + source à <span class=\"kw-bio\">CV détectable</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Trithérapie</span> (<span class=\"kw-ttt\">ténofovir + emtricitabine + rilpivirine</span>) en <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-chiffre\">28 jours</span> ; kit <span class=\"kw-chiffre\">48 h</span> puis consultation référent à <span class=\"kw-chiffre\">2-4 jours</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Créatinine</span> + <span class=\"kw-bio\">transaminases</span> à <span class=\"kw-chiffre\">J15</span> ; <span class=\"kw-bio\">sérologie VIH</span> à <span class=\"kw-chiffre\">6 semaines</span> et <span class=\"kw-chiffre\">3 mois</span> ; <span class=\"kw-ttt\">préservatif</span> jusqu’à <span class=\"kw-chiffre\">12 semaines</span>.</li></ul>"},{"id":"t-aes-notpe","kind":"terminal","label":"Pas de TPE — surveillance","color":"green","detail":"<h4>Conduite</h4><ul><li>Exposition à faible risque (autres cas, ou source <span class=\"kw-etio\">VIH</span> à <span class=\"kw-bio\">CV indétectable</span> sous ARV) : <span class=\"kw-alerte\">pas de TPE</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Sérologie VIH</span> à <span class=\"kw-chiffre\">6 semaines</span> ; <span class=\"kw-ttt\">séro-vaccination VHB</span> selon statut ; <span class=\"kw-def\">surveillance</span> <span class=\"kw-etio\">VHC</span>.</li></ul>"},{"id":"q-sex","kind":"decision","label":"Type de rapport × statut de la source","branches":[{"to":"t-sex-tpe","label":"Rapport pénétrant ou fellation réceptive avec éjaculation + CV détectable / inconnue (prévalence élevée)","color":"red"},{"to":"t-sex-notpe","label":"Fellation sans éjaculation / CV indétectable / prévalence faible","color":"green"},{"to":"t-viol","label":"Contexte de violences sexuelles (viol)","color":"amber"}]},{"id":"t-sex-tpe","kind":"terminal","label":"TPE VIH indiqué","color":"red","detail":"<h4>Indication</h4><ul><li><span class=\"kw-clinique\">Les</span> <strong>2 conditions</strong> réunies : rapport <span class=\"kw-clinique\">anal</span> / <span class=\"kw-clinique\">vaginal</span> (insertif ou réceptif) ou <span class=\"kw-clinique\">fellation réceptive avec éjaculation</span>, ET source à <span class=\"kw-bio\">CV détectable</span> ou <span class=\"kw-bio\">sérologie inconnue</span> en groupe à <span class=\"kw-alerte\">prévalence élevée</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Trithérapie</span> en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 4 h</span>, max <span class=\"kw-chiffre\">48 h</span>), <span class=\"kw-chiffre\">28 jours</span> ; bilan <span class=\"kw-clinique\">IST</span> avec <span class=\"kw-bio\">PCR chlamydia et gonocoque</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Sérologie VIH</span> à <span class=\"kw-chiffre\">6 semaines</span> et <span class=\"kw-chiffre\">3 mois</span> ; <span class=\"kw-ttt\">préservatif</span> jusqu’à <span class=\"kw-chiffre\">12 semaines</span>.</li></ul>"},{"id":"t-sex-notpe","kind":"terminal","label":"Pas de TPE — surveillance","color":"green","detail":"<h4>Conduite</h4><ul><li>Fellation insertive ou réceptive <span class=\"kw-clinique\">sans éjaculation</span>, ou source à <span class=\"kw-bio\">CV indétectable</span>, ou <span class=\"kw-bio\">sérologie</span> inconnue en <span class=\"kw-def\">prévalence</span> faible : <span class=\"kw-alerte\">pas de TPE</span>.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-bio\">Sérologie VIH</span> à <span class=\"kw-chiffre\">6 semaines</span> ; séro-<span class=\"kw-ttt\">vaccination</span> <span class=\"kw-etio\">VHB</span> et <span class=\"kw-def\">surveillance</span> <span class=\"kw-etio\">VHC</span> selon le contexte.</li></ul>"},{"id":"t-viol","kind":"terminal","label":"Prise en charge spécifique du viol","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-clinique\">Évaluation médico-légale</span> (légiste, réquisition) + <span class=\"kw-clinique\">évaluation des risques infectieux et de grossesse</span>.</li><li>Bilan : <span class=\"kw-bio\">VIH</span>, <span class=\"kw-bio\">VDRL-TPHA</span>, <span class=\"kw-bio\">VHB</span>, <span class=\"kw-bio\">VHC</span> ; récupérer la <span class=\"kw-clinique\">date des dernières règles</span>.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Contraception d’urgence</span> : <span class=\"kw-ttt\">lévonorgestrel</span> <span class=\"kw-chiffre\">1 cp</span>.</li><li><span class=\"kw-ttt\">TPE</span> si indiqué ; <span class=\"kw-ttt\">séro-vaccination VHB</span> si indiquée.</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prise en compte systématique du <span class=\"kw-alerte\">risque VHC</span> (rapport traumatique) : <span class=\"kw-def\">surveillance</span> clinique et <span class=\"kw-ttt\">biologique</span>.</li></ul>"},{"id":"t-drogue","kind":"terminal","label":"TPE selon statut source + séro-vaccination VHB + surveillance VHC","color":"amber","detail":"<h4>Indication</h4><ul><li><span class=\"kw-ttt\">TPE</span> si source à <span class=\"kw-bio\">CV détectable</span> ou <span class=\"kw-bio\">statut VIH inconnu</span>, en cas de partage de l’<span class=\"kw-clinique\">aiguille</span>, de la <span class=\"kw-clinique\">seringue</span> ou de la préparation.</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Séro-vaccination VHB</span> selon le statut immunitaire ; <span class=\"kw-clinique\">surveillance VHC</span> selon <span class=\"kw-clinique\">les</span> mêmes modalités qu’un AES (pas de prophylaxie <span class=\"kw-etio\">VHC</span>).</li></ul>"}]},"cards":[{"i":"2e69788c47d2","n":366,"o":"366-1","u":"Définition","t":"Connaître la définition d’un accident d’exposition accidentelle aux liquides biologiques (EALB) et les situations s’y rapportant","q":"Quel est le délai idéal et le délai maximal pour la prise en charge d'un EALB pour l'efficacité du traitement post-exposition ?","a":"<p>Un EALB est une <strong>urgence médicale</strong>. Il faut agir idéalement dans les <strong>moins de 4 heures</strong> following exposure. À défaut, l'intervention doit avoir lieu dans les <strong>moins de 48 heures</strong>. Au-delà de ce délai de 48 heures, le traitement post-exposition (TPE) est considéré comme <strong>inefficace</strong>.</p>"},{"i":"47461b3215e0","n":366,"o":"366-1","u":"Définition","t":"Connaître la définition d’un accident d’exposition accidentelle aux liquides biologiques (EALB) et les situations s’y rapportant","q":"Quelle est la définition d'un accident d'exposition aux liquides biologiques (EALB) ?","a":"<p>Un EALB, également appelé AEV (accident d'exposition au risque de transmission virale), est tout <strong>contact accidentel avec du sang ou un liquide biologique potentiellement contaminant</strong>, qui expose la personne aux trois principaux virus à transmission par le sang : le <strong>VIH</strong>, le <strong>VHB</strong> et le <strong>VHC</strong>.</p>"},{"i":"68dc82741c9e","n":366,"o":"366-1","u":"Définition","t":"Connaître la définition d’un accident d’exposition accidentelle aux liquides biologiques (EALB) et les situations s’y rapportant","q":"Quels sont les différents contextes et mécanismes d'un EALB en milieu professionnel ?","a":"<p>En milieu professionnel, on parle d'<strong>AES (accident d'exposition au sang)</strong>. Les mécanismes d'exposition incluent :</p><ul><li>Une <strong>piqûre avec une aiguille</strong>.</li><li>Une <strong>coupure avec un objet tranchant</strong> (bistouri, verre cassé).</li><li>Une <strong>projection</strong> de liquide biologique sur une <strong>plaie</strong>, une <strong>peau lésée</strong> ou une <strong>muqueuse</strong> (yeux, bouche).</li></ul>"},{"i":"93fbdd25e301","n":366,"o":"366-1","u":"Définition","t":"Connaître la définition d’un accident d’exposition accidentelle aux liquides biologiques (EALB) et les situations s’y rapportant","q":"Quels sont les contextes d'exposition aux liquides biologiques non professionnels ?","a":"<p>En dehors du cadre professionnel, les expositions aux liquides biologiques peuvent survenir dans deux grands contextes :</p><ul><li>L'<strong>exposition sexuelle</strong>, qui est alors appelée <strong>AES (accident d'exposition sexuelle)</strong>.</li><li>Le <strong>partage de matériel d'injection de drogues</strong> (aiguilles, seringues).</li></ul>"},{"i":"1ee6dabe0526","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Quels sont les facteurs déterminant le niveau de risque de transmission lors d'une Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Le niveau de risque de transmission d'une infection lors d'une EALB dépend de :</p><ul><li>Le <strong>virus</strong> en cause.</li><li>La <strong>nature</strong> de l'exposition.</li><li>Le <strong>statut sérologique</strong> de la personne source.</li></ul>"},{"i":"4d2867d6527b","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Existe-t-il une prophylaxie ou un vaccin efficace contre le VHC après une Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Non, il n'existe <strong>aucune prophylaxie</strong> ni <strong>vaccin disponible</strong> pour le <strong>VHC</strong> après une EALB. La prise en charge consiste en une surveillance et, si nécessaire, un traitement en cas d'infection aiguë.</p>"},{"i":"9f390eee2f16","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Quels sont les trois principaux agents infectieux viraux à transmission sanguine concernés par une Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Les trois virus à transmission sanguine concernés par un EALB sont :</p><ul><li>Le <strong>VIH</strong> (Virus de l'Immunodéficience Humaine).</li><li>Le <strong>VHB</strong> (Virus de l'Hépatite B).</li><li>Le <strong>VHC</strong> (Virus de l'Hépatite C).</li></ul>"},{"i":"af02c3fe0a95","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Quel est le liquide biologique le plus à risque en cas d'Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Le <strong>sang</strong> est le liquide biologique le plus à risque en cas d'EALB.</p>"},{"i":"d418c5bec3a3","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Quelle est la particularité de la prévention du VHB suite à une Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Pour le <strong>VHB</strong>, la transmission est la plus élevée des trois virus. La prévention spécifique repose sur la <strong>vaccination</strong>, potentiellement associée à l'administration d'<strong>immunoglobulines</strong>, selon le statut de la personne exposée et de la source.</p>"},{"i":"f24a8ad7acfe","n":366,"o":"366-2","u":"Définition","t":"Connaître les agents infectieux à risque de transmission lors d’un EALB","q":"Quelles sont les spécificités de la prévention du VIH après une Exposition Accidentelle au Liquide Biologique (EALB) ?","a":"<p>Pour le <strong>VIH</strong>, le risque de séroconversion est maîtrisé si la prise en charge est rapide, notamment par une <strong>Prophylaxie Post-Exposition (TPE) antirétrovirale</strong> d'une durée de <strong>28 jours</strong>.</p>"},{"i":"2edb0e1a49e5","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Quel est le risque de transmission du VHC lors d'une exposition accidentelle aux liquides biologiques et dans quelles circonstances ce risque est-il significatif par voie sexuelle ?","a":"<p>Le risque de transmission du VHC est <strong>inférieur à 3 %</strong> lors d'une AES. Par voie sexuelle, ce risque n'est significatif que si le rapport est <strong>traumatique</strong> (impliquant un saignement ou un viol).</p>"},{"i":"5c1142479241","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Concernant le VIH, quel est le taux de risque de transmission lors d'une exposition percutanée par accident d'exposition au sang (AES) et quels sont les facteurs qui augmentent ce risque ?","a":"<p>Le taux de risque de transmission du VIH lors d'une exposition percutanée par AES est d'environ <strong>0,3 %</strong> si la source n'est pas traitée. Le risque est augmenté dans les situations suivantes :</p><ul><li>Source non traitée par <strong>antirétroviraux</strong>.</li><li><strong>Charge virale élevée</strong> de la personne source.</li><li><strong>Blessure profonde</strong> avec une aiguille creuse contaminée contenant du <strong>sang</strong>.</li></ul>"},{"i":"70f189cf8558","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Quel est le risque de transmission du VHB lors d'une AES en cas de source Ag HBe positive et virémique ?","a":"<p>Le risque de transmission du VHB lors d'une AES est d'environ <strong>40 %</strong>, à condition que la source soit <strong>Ag HBe positive et virémique</strong>, et que le sujet exposé ne soit <strong>pas immunisé</strong>.</p>"},{"i":"c1279b8051cf","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Quels sont les trois principaux facteurs généraux de risque de transmission d'une exposition accidentelle aux liquides biologiques (EALB) ?","a":"<p>Les trois facteurs principaux sont :</p><ul><li>Le <strong>virus</strong> en cause.</li><li>Le <strong>type d'exposition</strong> (par exemple, cutanéo-muqueuse versus sexuelle).</li><li>Les <strong>cofacteurs</strong> spécifiques à chaque situation.</li></ul>"},{"i":"e4bcaf3c0efa","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Outre les AES et les expositions sexuelles, quelle autre voie de transmission est commune aux VIH, VHB et VHC ?","a":"<p>Les trois virus (VIH, VHB, VHC) peuvent également se transmettre par le <strong>partage de matériel d'injection de drogues</strong>. Cela inclut non seulement les aiguilles et seringues, mais aussi les pailles d'inhalation, les cotons et les cuillers.</p>"},{"i":"f3cf3c20b358","n":366,"o":"366-3","u":"Définition","t":"Connaître les facteurs de risque de transmission liés aux EALB","q":"Dans le cadre d'une exposition sexuelle au VIH, quels sont les taux de transmission associés aux rapports anaux réceptifs et vaginaux insertifs, et quels sont les facteurs influençant ce risque ?","a":"<p>Les taux de transmission du VIH via l'exposition sexuelle sont :</p><ul><li><strong>1 %</strong> pour un <strong>rapport anal réceptif</strong>.</li><li><strong>0,1 %</strong> pour un <strong>rapport vaginal insertif</strong>.</li></ul><p>Les facteurs augmentant le risque sont :</p><ul><li>Présence de <strong>lésions muqueuses</strong> ou d'une <strong>IST</strong>.</li><li><strong>Menstruations ou saignement</strong>.</li><li><strong>Viol</strong>.</li></ul><p>Les facteurs diminuant le risque sont :</p><ul><li>La <strong>circoncision</strong> (par kératinisation du gland).</li><li>Un traitement <strong>antirétroviral (ARV)</strong> chez le partenaire infecté avec une <strong>charge virale indétectable</strong>. Le risque est nul pour un rapport vaginal non traumatique si la charge virale est indétectable depuis plus de 6 mois sous ARV.</p></ul>"},{"i":"4b8cd30262b9","n":366,"o":"366-4","u":"Prise en charge","t":"Décrire les soins locaux immédiats en cas d’accident d’exposition au sang (AES)","q":"Quels sont les soins locaux immédiats à apporter à une blessure cutanée (piqûre, coupure) après exposition accidentelle au sang (AES) ?","a":"<ul><li><strong>Nettoyage immédiat</strong> à l'<strong>eau courante et au savon</strong> pour la détersion et l'élimination des matières organiques.</li><li><strong>Rinçage</strong>.</li><li><strong>Antisepsie</strong> par contact d'un antiseptique pendant <strong>au moins 5 minutes</strong>.</li></ul>"},{"i":"54c9c7656c0e","n":366,"o":"366-4","u":"Prise en charge","t":"Décrire les soins locaux immédiats en cas d’accident d’exposition au sang (AES)","q":"Quel est le piège à éviter concernant les soins locaux en cas de blessure cutanée après exposition accidentelle au sang (AES) ?","a":"<p>Le piège est de <strong>ne pas utiliser de produit hydro-alcoolique sur une plaie</strong>, car cela favorise le saignement et donc la transmission. Il ne faut également <strong>pas chercher à faire saigner la plaie</strong>.</p>"},{"i":"de658acd1a08","n":366,"o":"366-4","u":"Prise en charge","t":"Décrire les soins locaux immédiats en cas d’accident d’exposition au sang (AES)","q":"Quelle est la toute première étape de la prise en charge d'une blessure par piqûre ou coupure suite à une exposition accidentelle au sang (AES) ?","a":"<p>La toute première étape est de <strong>ne pas faire saigner</strong> la blessure. Le saignement crée une brèche capillaire qui favorise l'infection.</p>"},{"i":"f68303398831","n":366,"o":"366-4","u":"Prise en charge","t":"Décrire les soins locaux immédiats en cas d’accident d’exposition au sang (AES)","q":"Quelle est la conduite à tenir immédiate en cas de projection de liquides biologiques sur une muqueuse (œil, bouche) ?","a":"<p>Il faut procéder à un <strong>rinçage immédiat et abondant</strong> avec du <strong>sérum physiologique</strong> (ou de l'eau) pendant <strong>au moins 5 minutes</strong>.</p>"},{"i":"0f5b49fbdd16","n":366,"o":"366-5","u":"Prise en charge","t":"Connaître les modalités de prescription des sérologies à réaliser chez la personne source au cours des EALB","q":"Dans le cadre de l'exposition accidentelle aux liquides biologiques (EALB), quel est l'objectif principal de la recherche du statut sérologique chez la personne source ?","a":"<p>L'objectif est d'évaluer le risque de transmission d'agents pathogènes (VIH, VHB, VHC) à la personne exposée et d'orienter la prise en charge post-exposition, notamment l'indication d'un Traitement Post-Exposition (TPE).</p>"},{"i":"18fb6525b56c","n":366,"o":"366-5","u":"Prise en charge","t":"Connaître les modalités de prescription des sérologies à réaliser chez la personne source au cours des EALB","q":"Dans quel cas la sérologie VHB est-elle indiquée chez la personne source lors d'une exposition accidentelle aux liquides biologiques, et quels examens complémentaires sont réalisés si elle est positive ?","a":"<p>La sérologie VHB n'est <strong>pas systématique</strong> et est indiquée <strong>uniquement si la victime n'est pas immunisée</strong> contre le VHB. L'immunité est prouvée par la présence d'anticorps anti-HBs (<strong>Ac anti-HBs > 10 UI/L</strong>) ou des antécédents de vaccination efficace. Si une recherche d'<strong>Ag HBs</strong> est positive chez la source, il faut rechercher la réplication virale par un dosage d'<strong>ADN VHB</strong>.</p>"},{"i":"b6e0992c17f4","n":366,"o":"366-5","u":"Prise en charge","t":"Connaître les modalités de prescription des sérologies à réaliser chez la personne source au cours des EALB","q":"Quelles sérologies sont systématiquement recherchées chez la personne source après une exposition accidentelle aux liquides biologiques et avec quelles particularités ?","a":"<ul><li><strong>Sérologie VHC</strong> : Si positive, il faut rechercher la réplication virale par un dosage de l'<strong>ARN VHC</strong>.</li><li><strong>Sérologie VIH</strong> : Il faut privilégier les <strong>Tests de Diagnostic Rapide (TDR)</strong> pour avoir un résultat en <strong>moins d'une heure</strong>. Si positif, il faut réaliser une charge virale VIH en urgence et un génotype de résistance aux antirétroviraux. Le résultat du TDR VIH est crucial car il conditionne l'indication du TPE chez l'exposé.</li></ul>"},{"i":"19b879abd1a2","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la conduite à tenir après exposition accidentelle au VHB chez un sujet exposé vacciné répondeur (Ac anti-HBs > 10 UI/L) ?","a":"<p>Il n'y a <strong>rien à faire</strong>, le sujet exposé est considéré comme protégé, que la source soit Ag HBs positif ou que son statut soit inconnu.</p>"},{"i":"5f779ca0e0f2","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la conduite à tenir après exposition accidentelle au VHB chez un sujet exposé non vacciné si la source est Ag HBs inconnu ?","a":"<p>Il faut débuter une <strong>vaccination</strong>. Des <strong>immunoglobulines</strong> peuvent être ajoutées si la source est à risque (pays d'endémie, HSH, usager de drogue IV, partenaires multiples).</p>"},{"i":"669e943b9bf9","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la conduite à tenir après exposition accidentelle au VHB chez un sujet vacciné jamais contrôlé ?","a":"<ul><li>Si les Ac anti-HBs sont <strong>&lt; 10 UI/L</strong> : une <strong>vaccination</strong> est indiquée.</li><li>Si les Ac anti-HBs sont <strong>&gt; 10 UI/L</strong> : le sujet est considéré comme répondeur et protégé, le risque de transmission est nul.</li></ul>"},{"i":"76fabf374917","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la conduite à tenir après exposition accidentelle au VHB chez un sujet exposé non vacciné si la source est Ag HBs positif ?","a":"<p>Il faut administrer des <strong>immunoglobulines</strong> et débuter une <strong>vaccination</strong> contre le VHB.</p>"},{"i":"85835cca2032","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la base de la décision de séro-vaccination après une exposition accidentelle au VHB ?","a":"<p>La décision repose sur le croisement entre le <strong>statut vaccinal de la personne exposée</strong> et le <strong>statut VHB (Ag HBs) de la source</strong>.</p>"},{"i":"b6f50ec5f744","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quelle est la conduite à tenir après exposition accidentelle au VHB chez un sujet vacciné non répondeur ou de titre inconnu, si la source est Ag HBs positif ?","a":"<p>Il faut administrer des <strong>immunoglobulines</strong>. Elles ne sont pas nécessaires si l'ADN VHB est indétectable chez la source et qu'un traitement post-exposition par ténofovir est mis en place.</p>"},{"i":"d29356e62e7e","n":366,"o":"366-8","u":"Prise en charge","t":"Connaître les indications de séro-vaccination après AES exposant au virus de l’hépatite B (VHB)","q":"Quel est le suivi biologique recommandé chez un sujet non protégé après une exposition accidentelle au VHB ?","a":"<p>Un suivi des <strong>transaminases</strong> et des <strong>marqueurs VHB</strong> (Ag HBs, Ac anti-HBc, Ac anti-HBs) doit être réalisé à <strong>3 mois</strong>.</p>"},{"i":"659c2991ee80","n":366,"o":"366-9","u":"Prise en charge","t":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","q":"Quelles infections, liées à un Accident d'Exposition au Sang (AES), peuvent être reconnues en maladie professionnelle chez un soignant ?","a":"<p>Les infections pouvant être reconnues en <strong>maladie professionnelle (MP)</strong> chez un soignant après un AES sont le <strong>VHC, le VHB, la tuberculose, la rage et la gale</strong>, conformément aux tableaux de maladies professionnelles. Le VIH ne peut pas être reconnu en MP.</p>"},{"i":"9c42eb739a6e","n":366,"o":"366-9","u":"Prise en charge","t":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","q":"Quelle est la vaccination obligatoire un élément majeur de prévention des Accidents d'Exposition au Sang (AES) chez les professionnels de santé ?","a":"<p>La <strong>vaccination contre le Virus de l'Hépatite B (VHB)</strong> est obligatoire chez les professionnels de santé et constitue un élément majeur de prévention des Accidents d'Exposition au Sang (AES).</p>"},{"i":"b2225a3e190f","n":366,"o":"366-9","u":"Prise en charge","t":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","q":"Comment une infection acquise après un Accident d'Exposition au Sang (AES), notamment le VIH, peut-elle être reconnue en accident du travail ?","a":"<p>Toute infection acquise après un AES peut être reconnue en <strong>accident du travail (AT)</strong>, y compris le VIH. Cela nécessite une <strong>déclaration par l'employeur &lt; 48 heures</strong> et un <strong>certificat médical initial</strong>. Pour la reconnaissance d'une infection VIH en AT, des critères spécifiques doivent être remplis :</p><ul><li>La source doit être <strong>porteuse du VIH</strong> au moment de l'accident.</li><li>La <strong>sérologie VIH de l'exposé doit être négative dans les 8 jours</strong> suivant l'exposition.</li><li>Une <strong>séroconversion</strong> doit survenir dans un délai de <strong>6 à 12 semaines</strong>.</li></ul>"},{"i":"bfa8655e1ffc","n":366,"o":"366-9","u":"Prise en charge","t":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","q":"Quels sont les trois principaux piliers des précautions standard d'hygiène pour prévenir un Accident d'Exposition au Sang (AES) ?","a":"<p>Les trois principaux piliers sont :</p><ul><li>Le <strong>port de gants</strong> pour les gestes à risque.</li><li>Ne jamais <strong>recapuchonner les aiguilles</strong>.</li><li>Jeter immédiatement les objets piquants ou tranchants dans un <strong>conteneur d'Objets Piquants, Coupants ou Tranchants (OPCT) ad hoc</strong>.</li></ul>"},{"i":"fd973e40f97b","n":366,"o":"366-9","u":"Prise en charge","t":"Connaître les principaux facteurs de prévention d’un AES en milieu de soin","q":"Quel est l'impact de l'utilisation de matériel sécurisé sur la fréquence des Accidents d'Exposition au Sang (AES) ?","a":"<p>La mise à disposition de <strong>matériel sécurisé</strong> a permis une <strong>diminution notable</strong> de la fréquence des Accidents d'Exposition au Sang (AES) en milieu hospitalier.</p>"}]};